export const meta = {
  name: 'panel-v3-build',
  description: 'Build Panel V3 per PANEL_V3_SPEC.md: 3-file refactor, Mission Control, Economy graphs, Stat Wall, adversarially verified',
  phases: [
    { title: 'Refactor', detail: '3-way split, zero feature change' },
    { title: 'Build', detail: 'Mission Control → Economy → Stat Wall (sequential, shared files)' },
    { title: 'Verify', detail: 'adversarial wiring+honesty checks, repair loop' },
  ],
}

const REPO = '/home/phili/tools/cavecrew-mcp'
const COMMON = `Repo: ${REPO}. THE SPEC: read cave/PANEL_V3_SPEC.md FULLY first — it is the contract (data inventory, feature spec, honesty rules, architecture). Also read cave/PANEL.md.
HARD RULES for every agent: (1) never touch port 3200 (live panel) or POST to live bot runners 3201-3208 — GET /status//events read-only is fine; dev panel instance = PANEL_PORT=3290, mock runner = 3291 only, kill both after tests. (2) no external libs/CDN — vanilla ESM, no build step, hand-rolled inline SVG for charts. (3) STYLE: all colors/spacing/type via CSS custom properties in one :root token block (current dark-ops palette as baseline values) — a later skin pass swaps tokens only. (4) HONESTY states per spec: missing data source → hide section or show explicit "no data yet", NEVER fabricate. (5) node --check every touched file + curl the SERVED page and served /panel.js and verify (client checks: every paint*/fetch pair wired, every getElementById id exists in served HTML). (6) commit your stage when green (repo commit style, SHOUTY prefix), NO push. (7) files you may touch: cave/panel.mjs, cave/panel-data.mjs, cave/panel-client.js, cave/PANEL.md — NOTHING else (no runner.js/skills.js — those are another lane).`

phase('Refactor')
const refactor = await agent(`${COMMON}
TASK — PHASE 1, the 3-way split (spec's architecture section): split cave/panel.mjs into (a) panel.mjs = HTTP server + routing only, (b) cave/panel-data.mjs = ALL server-side parsers/data assembly (fleet poll, TODO parse, vault/audit read, + new: BASE_ANCHOR constant {x:11,y:89,z:55} exported, ledger reader for cave/ledger/*.jsonl, deaths reader cave/deaths/*.json, fel-relation.json reader, missions reader cave/missions/*.jsonl tolerant-if-missing), (c) cave/panel-client.js = the ENTIRE client script as a real .js file served via GET /panel.js (replaces the inline template-literal — unescape any double-backslash regexes that existed ONLY to survive the template literal, e.g. the SUPPRESSED_RE and timestamp-trim patterns). ZERO feature/visual change this phase. Also add the :root CSS token block (extract current hardcoded colors into tokens, apply via var()). Test: boot dev instance 3290 against live 3201/3202 read-only, curl page + /panel.js + /api/fleet + /api/todo + /api/vault — all must serve identical-behavior content; run the wiring check. Commit. Return: file sizes, what moved where, test results, commit hash.`, { model: 'sonnet', label: 'refactor:3-way-split' })

phase('Build')
const buildStages = [
  { label: 'build:mission-control', brief: `TASK — MISSION CONTROL upgrade per spec section (extends existing fleet cards, does not replace): per-bot card adds (a) DISTANCE FROM BASE: horizontal meters + compass direction (N/NE/E/...) + vertical delta, computed from BASE_ANCHOR in panel-data.mjs; (b) task line shows kind + detail + "via <source>" (existing chip logic stays); (c) tool/durability chips: WHEN /status inventory items carry durabilityUsed/maxDurability render icon+bar (green>50%, amber 30-50%, red<30% per spec) — when fields absent (runner not upgraded yet) show plain item chips exactly as today, zero fake bars; (d) DRILLDOWN: click card header toggles an expanded panel (same max-height motion language as event feed) showing full inventory grid, event feed (existing), mission history list from /api/missions WHEN the missions source exists else a quiet "keine Missions-Historie (runner-update ausstehend)" line. New /api/missions endpoint in panel.mjs reading via panel-data.mjs.` },
  { label: 'build:economy', brief: `TASK — ECONOMY section per spec: new full-width section between fleet grid and Tribe Board. Data: panel-data.mjs ledger reader aggregates cave/ledger/*.jsonl into per-item time-bucketed net series (buckets: 10-min, last 6h window) for key items (iron_ingot, raw_iron, wheat, bread, oak_log, cobblestone — show only items with ANY movement; ledger is young/sparse TODAY (few lines) so the section must look correct with 1-4 datapoints: render dots+line, show net totals + last movement time). Hand-rolled inline SVG sparklines (no lib), one per active item, token colors, hover shows exact value via <title>. Honesty: no ledger files → hide section; files but no parsed rows → "Ledger leer — Bewegungen erscheinen ab jetzt". New /api/economy endpoint.` },
  { label: 'build:stat-wall', brief: `TASK — TRIBE STAT WALL per spec: prominent big-number row at top (below header, above fleet grid): (1) Tage/Stunden ohne Tod — from cave/deaths/*.json: empty dir = "0 Tode seit Relaunch" with relaunch date, any death = time since last; (2) Erz gebankt — iron_ingot+raw_iron+raw_copper+coal totals from audit-snapshot.json vault data (stale-age note per vault rules); (3) Brot-Vorrat — bread total from audit snapshot; (4) Missionen heute — count from missions jsonl WHEN exists else tile hidden; (5) FEL-Status — from cave/fel-relation.json (headline + status color: allied=green), hide tile if file missing. Big-number typography via tokens, glance-readable. New /api/statwall endpoint. Also: Vault + Tribe Board sections stay below — check final page ordering matches spec's wall layout.` },
]
await pipeline([0], async () => {
  let prev = ''
  for (const s of buildStages) {
    prev = await agent(`${COMMON}
CONTEXT from previous stage: ${String(prev).slice(0, 1500)}
${s.brief}
Build on current HEAD of the three panel files (earlier stages committed). Test on 3290 (live read-only data) + wiring check + node --check. Commit. Return: file:line summary, endpoint shapes, test evidence, commit hash.`, { model: 'sonnet', label: s.label, phase: 'Build' })
  }
  return prev
})

phase('Verify')
const VERDICT = { type: 'object', properties: { ship: { type: 'boolean' }, findings: { type: 'array', items: { type: 'object', properties: { severity: { type: 'string' }, claim: { type: 'string' }, evidence: { type: 'string' } }, required: ['severity', 'claim', 'evidence'] } } }, required: ['ship', 'findings'] }
const vPrompt = (lens) => `${COMMON}
ADVERSARIAL VERIFY of the committed Panel V3 work (git log today's PANEL commits, diff against pre-refactor state). Lens: ${lens}. Method: boot dev instance 3290 against live runners (read-only), curl SERVED page + /panel.js + every /api/* endpoint; check with real responses, not source reading alone. ship=false on any real defect. Kill dev instance after.`
let verdicts = await parallel([
  () => agent(vPrompt('WIRING + REGRESSION: every paint*/fetch pair called, every DOM id referenced exists, all v2 features (guard chips, panic flag, event feed, source chips, Tribe Board, Vault) still work identically, /panel.js serves valid JS, no template-literal escaping remnants, refresh loop consumes all new endpoints'), { label: 'verify:wiring', effort: 'high', phase: 'Verify', schema: VERDICT }),
  () => agent(vPrompt('HONESTY + DATA CORRECTNESS: distance math right (check against live bot positions by hand), no fabricated data anywhere (durability absent today → no bars shown; missions absent → hidden/quiet line; sparse ledger renders truthfully), stale/error/empty states per spec, stat-wall numbers match their sources exactly (recompute by hand from the real files)'), { label: 'verify:honesty', effort: 'high', phase: 'Verify', schema: VERDICT }),
])

let round = 0
while (round < 2) {
  const clean = verdicts.filter(Boolean)
  const blockers = clean.flatMap(v => v.ship ? [] : v.findings.filter(f => f.severity !== 'minor'))
  if (clean.length && blockers.length === 0) break
  round++
  log(`repair round ${round}: ${blockers.length} blockers`)
  await agent(`${COMMON}
REPAIR these verified findings in the panel files (fix forward, don't revert the build):
${JSON.stringify(blockers, null, 2)}
node --check + re-test on 3290 + wiring check. Commit. Return change summary.`, { model: 'sonnet', label: `repair:${round}`, phase: 'Verify' })
  verdicts = await parallel([
    () => agent(vPrompt(`POST-REPAIR round ${round}: full re-verify, both wiring and honesty lenses`), { label: `reverify:${round}`, effort: 'high', phase: 'Verify', schema: VERDICT }),
  ])
}

const final = verdicts.filter(Boolean)
return { ship: final.length > 0 && final.every(v => v.ship), remaining: final.flatMap(v => v.findings) }

