input.script:
export const meta = {
  name: 'house-schematic-hunt',
  description: 'Find + download house schematics online, validate NBT, material plan vs tribe stocks',
  phases: [
    { title: 'Hunt', detail: '2 hunters, different sources' },
    { title: 'Validate', detail: 'parse NBT, dims, palette counts' },
    { title: 'Decide', detail: 'judge picks winner + material plan' },
  ],
}

const DIR = '/home/phili/tools/cavecrew-mcp/cave/schematics'
const CAVEMAN = '\n\nReport style: caveman-compressed. Short lines. No filler. Technical values exact.'

const COMMON_HUNT = `
MISSION: find and DOWNLOAD 2-3 Minecraft house schematic files (.schem or .schematic) for a SURVIVAL build on a hilltop by a small bot tribe (MC 1.21.11, Baritone #build).
HARD REQUIREMENTS:
- Actually download the files to ${DIR}/ (curl -L, prefix filename with your hunter key to avoid collisions).
- Verify each file is real binary NBT, not an HTML error page: first bytes gzip magic (1f 8b) or NBT compound (0a). Use: xxd -l 4 <file>. Delete and discard HTML junk.
- Style: cottage / medieval / rustic house. Cool-looking on a hill. Modest: footprint roughly <= 20x20 preferred, 1-3 floors.
- SURVIVAL-friendly palette preferred: oak/spruce planks+logs, cobblestone, stone, stairs, slabs, glass panes, fences. AVOID concrete, terracotta, quartz, prismarine-heavy builds.
- Skip any site requiring login/account for download. Skip paid.
- NEVER run git checkout/reset/stash. Only write files into ${DIR}/.
Return candidates you actually downloaded and byte-verified. Empty list is honest if nothing works.` + CAVEMAN

const HUNTERS = [
  { key: 'sites', prompt: `You are hunter "sites". Search schematic sites with direct downloads: abfielder.com (has direct .schem downloads + material lists), minecraftschematics sites, cubical.xyz exports, mcschematics forums. Use WebSearch + WebFetch to find pages, then curl -L the actual file links.` + COMMON_HUNT },
  { key: 'github', prompt: `You are hunter "github". Search GitHub for committed .schem/.schematic house files: GitHub code search (e.g. "cottage.schem", "house.schem", path:*.schem), schematic collection repos. Download via raw.githubusercontent.com URLs with curl -L.` + COMMON_HUNT },
]

const CAND = { type: 'object', required: ['candidates'], properties: { candidates: { type: 'array', items: { type: 'object', required: ['name', 'file', 'source'], properties: { name: { type: 'string' }, file: { type: 'string', description: 'absolute path of downloaded file' }, source: { type: 'string', description: 'URL it came from' }, note: { type: 'string' } } } } } }

const VAL = { type: 'object', required: ['name', 'file', 'parseOk'], properties: { name: { type: 'string' }, file: { type: 'string' }, parseOk: { type: 'boolean' }, format: { type: 'string', description: 'sponge-v2/sponge-v3/legacy-mcedit/litematic/unknown' }, width: { type: 'number' }, height: { type: 'number' }, length: { type: 'number' }, totalBlocks: { type: 'number', description: 'non-air block count' }, dataVersion: { type: 'number' }, paletteTop: { type: 'array', items: { type: 'object', required: ['block', 'count'], properties: { block: { type: 'string' }, count: { type: 'number' } } } }, note: { type: 'string' } } }

function validatePrompt(c) {
  return `Validate Minecraft schematic candidate "${c.name}" at file: ${c.file} (source: ${c.source}).
Write a small node script in the scratchpad (session scratchpad dir) and run it with cwd /home/phili/tools/cavecrew-mcp so require('prismarine-nbt') resolves (it is installed there). Parse the (possibly gzipped) NBT:
- Sponge .schem v2/v3: read Width/Height/Length, Palette (block -> index), BlockData (varint array) -> count blocks per palette entry, DataVersion.
- Legacy MCEdit .schematic: Blocks byte array + numeric IDs -> mark format legacy-mcedit, parseOk true only if structure reads; note that numeric IDs need conversion for MC 1.21.11 (risky).
Report: dims, total NON-AIR blocks, full palette counts (top 15 in paletteTop, air excluded), DataVersion (server is MC 1.21.11). parseOk=false if file corrupt/HTML/unreadable. Do not modify any repo files.` + CAVEMAN
}

const results = await pipeline(
  HUNTERS,
  h => agent(h.prompt, { label: `hunt:${h.key}`, phase: 'Hunt', model: 'sonnet', schema: CAND }),
  r => parallel(((r && r.candidates) || []).slice(0, 3).map(c => () =>
    agent(validatePrompt(c), { label: `validate:${c.name}`.slice(0, 40), phase: 'Validate', model: 'sonnet', schema: VAL })
  ))
)

const validated = results.filter(Boolean).flat().filter(Boolean).filter(v => v.parseOk)
log(`${validated.length} parseable candidates`)

const VERDICT = { type: 'object', required: ['fallbackGenerate'], properties: { winner: { type: 'string', description: 'file path of winning schematic' }, winnerName: { type: 'string' }, ranked: { type: 'array', items: { type: 'string' } }, substitutes: { type: 'array', items: { type: 'object', required: ['from', 'to'], properties: { from: { type: 'string' }, to: { type: 'string' }, reason: { type: 'string' } } } }, materials: { type: 'array', items: { type: 'object', required: ['item', 'count'], properties: { item: { type: 'string' }, count: { type: 'number' }, source: { type: 'string', description: 'how tribe gets it: chop/mine/smelt/craft/have' } } } }, warnings: { type: 'array', items: { type: 'string' } }, fallbackGenerate: { type: 'boolean', description: 'true if no candidate is buildable and we should generate our own schematic instead' }, reasoning: { type: 'string' } } }

if (validated.length === 0) {
  return { fallbackGenerate: true, reason: 'no parseable schematic downloaded', hunted: results }
}

const verdict = await agent(`You are the judge for the cavecrew hilltop-house schematic pick. Survival build, no cheating, MC 1.21.11, Baritone 1.17.0 #build executes it, a small bot tribe must GATHER every block (they are good at: oak logs->planks/stairs/slabs/fences, cobblestone/stone, sticks, torches, glass only if sand+furnace found, wool/beds NO, concrete/terracotta NO).
CANDIDATES (parsed ground truth): ${JSON.stringify(validated)}
Also read for stock context: /home/phili/tools/cavecrew-mcp/cave/BASE.md (chest inventory registry) and look for a chest audit snapshot json under /home/phili/tools/cavecrew-mcp/cave/ (ls for audit/vault json files, read newest if exists).
PICK the winner by: (1) survival-gatherable palette, (2) footprint 10-20 blocks per side ideal, (3) cool cottage/medieval look for a hilltop, (4) format safety (sponge .schem for 1.21.11 best; legacy-mcedit = high risk, only pick if nothing else). Then produce:
- substitutes: palette entries the tribe cannot gather -> nearest gatherable block or air (Baritone buildSubstitutes style).
- materials: full shopping list AFTER substitutes (item, count with ~10% waste buffer, source: have/chop/mine/smelt/craft).
- warnings: anything that can break the build (legacy format, waterlogged blocks, banners/entities not in palette counts, multi-part blocks like doors/beds counting weird).
- fallbackGenerate=false since candidates exist, unless ALL are truly unbuildable -> then true.
Do not modify any files.` + CAVEMAN, { label: 'judge', phase: 'Decide', schema: VERDICT })

return { verdict, validated }

